css:
.mdc-palette-k{
  --mdc-pk-bg:#0F121B;
  --mdc-pk-line:rgba(255,255,255,.09);
  --mdc-pk-txt:#E9ECF6;
  --mdc-pk-dim:#8A91A6;
  --mdc-pk-accent:#7FA0FF;
  box-sizing:border-box;width:100%;max-width:320px;margin:0 auto;
  font:500 12.5px/1.35 system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  color:var(--mdc-pk-txt);-webkit-font-smoothing:antialiased;
}
.mdc-palette-k *{box-sizing:border-box}
.mdc-palette-k-sheet{
  position:relative;border:1px solid var(--mdc-pk-line);border-radius:14px;overflow:hidden;
  background:linear-gradient(180deg,#161B27,var(--mdc-pk-bg) 42%);
  box-shadow:0 24px 44px -26px #000,0 0 0 1px rgba(127,160,255,.06) inset;
  animation:mdc-palette-k-in .34s cubic-bezier(.2,.9,.25,1) both;
}
.mdc-palette-k-sheet::before{content:"";position:absolute;inset:-40% 20% auto;height:70px;background:radial-gradient(50% 100% at 50% 0,rgba(127,160,255,.35),transparent 70%);pointer-events:none}
.mdc-palette-k-bar{display:flex;align-items:center;gap:8px;padding:10px 10px 9px;border-bottom:1px solid var(--mdc-pk-line);position:relative}
.mdc-palette-k-mag{width:14px;height:14px;flex:none;fill:none;stroke:var(--mdc-pk-dim);stroke-width:1.8;stroke-linecap:round}
.mdc-palette-k-input{
  flex:1;min-width:0;height:20px;border:0;padding:0;background:none;color:inherit;font:inherit;
}
.mdc-palette-k-input::placeholder{color:var(--mdc-pk-dim)}
.mdc-palette-k-input:focus{outline:none}
.mdc-palette-k-input:focus-visible{outline:none}
.mdc-palette-k-bar:focus-within{background:rgba(127,160,255,.05)}
.mdc-palette-k-bar:focus-within::after{content:"";position:absolute;left:0;right:0;bottom:-1px;height:1px;background:linear-gradient(90deg,transparent,var(--mdc-pk-accent),transparent)}
.mdc-palette-k-kbd{
  font:600 9.5px/1 ui-monospace,Menlo,monospace;color:var(--mdc-pk-dim);flex:none;
  padding:3px 5px;border:1px solid var(--mdc-pk-line);border-radius:5px;background:rgba(255,255,255,.04);
}
.mdc-palette-k-list{position:relative;list-style:none;margin:0;padding:5px;max-height:132px;overflow-y:auto;scrollbar-width:thin}
.mdc-palette-k-list::-webkit-scrollbar{width:6px}
.mdc-palette-k-list::-webkit-scrollbar-thumb{background:rgba(255,255,255,.12);border-radius:3px}
.mdc-palette-k-row{
  position:relative;display:flex;align-items:center;gap:9px;height:32px;padding:0 8px;border-radius:8px;cursor:pointer;
  color:var(--mdc-pk-dim);transition:background .14s ease,color .14s ease;
}
.mdc-palette-k-row[hidden]{display:none}
.mdc-palette-k-row.is-on{background:rgba(127,160,255,.14);color:var(--mdc-pk-txt)}
.mdc-palette-k-row.is-on::before{content:"";position:absolute;left:-5px;top:7px;bottom:7px;width:2px;border-radius:2px;background:var(--mdc-pk-accent)}
.mdc-palette-k-row.is-run{animation:mdc-palette-k-flash .42s ease both}
.mdc-palette-k-ico{width:14px;height:14px;flex:none;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.mdc-palette-k-row.is-on .mdc-palette-k-ico{stroke:var(--mdc-pk-accent)}
.mdc-palette-k-name{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mdc-palette-k-empty{margin:0;padding:16px 12px;text-align:center;color:var(--mdc-pk-dim);font-size:11.5px}
.mdc-palette-k-foot{
  display:flex;align-items:center;gap:10px;padding:7px 10px;border-top:1px solid var(--mdc-pk-line);
  background:rgba(0,0,0,.22);font-size:10px;color:var(--mdc-pk-dim);
}
.mdc-palette-k-hint{display:flex;align-items:center;gap:4px}
.mdc-palette-k-status{margin-left:auto;font:600 10px/1 ui-monospace,Menlo,monospace;color:#A9B3CC;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:130px}
@keyframes mdc-palette-k-in{from{opacity:0;transform:translateY(8px) scale(.97)}to{opacity:1;transform:none}}
@keyframes mdc-palette-k-flash{0%{background:rgba(127,160,255,.55)}100%{background:rgba(127,160,255,.14)}}
@media (prefers-reduced-motion: reduce){
.mdc-palette-k-sheet{animation:none}
.mdc-palette-k-row{transition:none}
.mdc-palette-k-row.is-run{animation:none}
}

js:
var input = root.querySelector('.mdc-palette-k-input');
var list = root.querySelector('.mdc-palette-k-list');
var rows = [].slice.call(root.querySelectorAll('.mdc-palette-k-row'));
var empty = root.querySelector('.mdc-palette-k-empty');
var status = root.querySelector('.mdc-palette-k-status');
var vis = rows.slice(), i = 0, timer = 0;

function fuzzy(hay, q){
  if (!q) return true;
  var p = 0;
  for (var k = 0; k < q.length; k++){
    p = hay.indexOf(q.charAt(k), p);
    if (p < 0) return false;
    p++;
  }
  return true;
}
function keep(el){
  var t = el.offsetTop, b = t + el.offsetHeight;
  if (t < list.scrollTop) list.scrollTop = t;
  else if (b > list.scrollTop + list.clientHeight) list.scrollTop = b - list.clientHeight;
}
function paint(){
  for (var k = 0; k < rows.length; k++){
    var on = rows[k] === vis[i];
    rows[k].classList.toggle('is-on', on);
    rows[k].setAttribute('aria-selected', on ? 'true' : 'false');
  }
  if (vis[i]) keep(vis[i]);
}
function filter(){
  var q = input.value.trim().toLowerCase();
  vis = [];
  for (var k = 0; k < rows.length; k++){
    var hit = fuzzy((rows[k].getAttribute('data-kw') || '').toLowerCase(), q);
    rows[k].hidden = !hit;
    if (hit) vis.push(rows[k]);
  }
  i = 0;
  empty.hidden = vis.length > 0;
  status.textContent = vis.length + (vis.length === 1 ? ' command' : ' commands');
  paint();
}
function run(el){
  if (!el) return;
  el.classList.add('is-run');
  status.textContent = 'Ran · ' + el.getAttribute('data-name');
  clearTimeout(timer);
  timer = setTimeout(function(){ el.classList.remove('is-run'); }, 460);
}
function step(d){
  if (!vis.length) return;
  i = (i + d + vis.length) % vis.length;
  paint();
}
input.addEventListener('input', filter);
input.addEventListener('keydown', function(e){
  if (e.key === 'ArrowDown'){ e.preventDefault(); step(1); }
  else if (e.key === 'ArrowUp'){ e.preventDefault(); step(-1); }
  else if (e.key === 'Home'){ e.preventDefault(); i = 0; paint(); }
  else if (e.key === 'End'){ e.preventDefault(); i = Math.max(0, vis.length - 1); paint(); }
  else if (e.key === 'Enter'){ e.preventDefault(); run(vis[i]); }
  else if (e.key === 'Escape' && input.value){ e.preventDefault(); input.value = ''; filter(); }
});
rows.forEach(function(r){
  r.addEventListener('mousemove', function(){
    var n = vis.indexOf(r);
    if (n >= 0 && n !== i){ i = n; paint(); }
  });
  r.addEventListener('click', function(){
    var n = vis.indexOf(r);
    if (n >= 0){ i = n; paint(); }
    run(r);
    input.focus();
  });
});
filter();

css:
