  --mdc-fz-dim:#5F6980;
  --mdc-fz-hit:#F3B44E;
  box-sizing:border-box;width:100%;max-width:320px;margin:0 auto;
  border:1px solid var(--mdc-fz-line);border-radius:10px;overflow:hidden;
  background:var(--mdc-fz-bg);color:var(--mdc-fz-txt);
  font:400 12px/1.4 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
}
.mdc-fuzzy-rank *{box-sizing:border-box}
.mdc-fuzzy-rank-head{display:flex;align-items:center;gap:7px;padding:8px 10px;border-bottom:1px solid var(--mdc-fz-line);background:linear-gradient(180deg,rgba(255,255,255,.05),transparent)}
.mdc-fuzzy-rank-prompt{color:var(--mdc-fz-hit);font-weight:700;animation:mdc-fuzzy-rank-blink 1.4s steps(1,end) infinite}
.mdc-fuzzy-rank-input{flex:1;min-width:0;height:18px;border:0;padding:0;background:none;color:#EEF2FA;font:inherit;letter-spacing:.02em}
