js:
var input = root.querySelector('.mdc-fuzzy-rank-input');
var list = root.querySelector('.mdc-fuzzy-rank-list');
var items = [].slice.call(root.querySelectorAll('.mdc-fuzzy-rank-item'));
var count = root.querySelector('.mdc-fuzzy-rank-count');
var log = root.querySelector('.mdc-fuzzy-rank-log');
var vis = [], i = 0, timer = 0;

function score(path, q){
  if (!q) return { s: 0, m: [] };
  var low = path.toLowerCase(), m = [], p = 0, s = 0, prev = -2;
  for (var k = 0; k < q.length; k++){
    p = low.indexOf(q.charAt(k), p);
    if (p < 0) return null;
    s += (p === prev + 1) ? 9 : 2;
    if (p === 0 || '/-._ '.indexOf(low.charAt(p - 1)) >= 0) s += 6;
    m.push(p);
    prev = p;
    p++;
  }
  return { s: Math.max(1, s - Math.round(path.length / 5)), m: m };
}
function label(el, path, m){
  var box = el.querySelector('.mdc-fuzzy-rank-path');
  box.textContent = '';
  for (var k = 0; k < path.length; k++){
    if (m.indexOf(k) >= 0){
      var b = document.createElement('b');
      b.className = 'mdc-fuzzy-rank-hit';
      b.textContent = path.charAt(k);
      box.appendChild(b);
    } else {
      box.appendChild(document.createTextNode(path.charAt(k)));
    }
  }
}
function keep(el){
  var t = el.offsetTop, b = t + el.offsetHeight;
  if (t < list.scrollTop) list.scrollTop = t;
  else if (b > list.scrollTop + list.clientHeight) list.scrollTop = b - list.clientHeight;
}
function paint(){
  items.forEach(function(el){
    var on = el === vis[i];
    el.classList.toggle('is-on', on);
    el.setAttribute('aria-selected', on ? 'true' : 'false');
  });
  if (vis[i]) keep(vis[i]);
}
function refresh(){
  var q = input.value.trim().toLowerCase();
  var hits = [];
  items.forEach(function(el){
    var path = el.getAttribute('data-path');
    var r = score(path, q);
    if (!r){ el.hidden = true; return; }
    el.hidden = false;
    el.setAttribute('data-score', String(r.s));
    label(el, path, r.m);
    hits.push(el);
  });
  hits.sort(function(a, b){
    return (+b.getAttribute('data-score')) - (+a.getAttribute('data-score'));
  });
  var top = hits.length ? Math.max(1, +hits[0].getAttribute('data-score')) : 1;
  hits.forEach(function(el){
    list.appendChild(el);
    var v = +el.getAttribute('data-score');
    el.querySelector('.mdc-fuzzy-rank-fill').style.width = (q ? Math.max(10, Math.round(100 * v / top)) : 0) + '%';
    el.querySelector('.mdc-fuzzy-rank-num').textContent = q ? String(v) : '·';
  });
  vis = hits;
  i = 0;
  count.textContent = hits.length + '/' + items.length;
  log.textContent = hits.length ? 'ranked by match density' : 'no match for "' + q + '"';
  paint();
}
function open(el){
  if (!el) return;
  el.classList.add('is-open');
  log.textContent = 'open ' + el.getAttribute('data-path');
  clearTimeout(timer);
  timer = setTimeout(function(){ el.classList.remove('is-open'); }, 520);
}
input.addEventListener('input', refresh);
input.addEventListener('keydown', function(e){
  if (e.key === 'ArrowDown'){ e.preventDefault(); if (vis.length){ i = (i + 1) % vis.length; paint(); } }
  else if (e.key === 'ArrowUp'){ e.preventDefault(); if (vis.length){ i = (i - 1 + vis.length) % vis.length; paint(); } }
  else if (e.key === 'Enter'){ e.preventDefault(); open(vis[i]); }
  else if (e.key === 'Escape' && input.value){ e.preventDefault(); input.value = ''; refresh(); }
});
items.forEach(function(el){
  el.addEventListener('mousemove', function(){
    var n = vis.indexOf(el);
    if (n >= 0 && n !== i){ i = n; paint(); }
  });
  el.addEventListener('click', function(){
    var n = vis.indexOf(el);
    if (n >= 0){ i = n; paint(); }
    open(el);
  });
});
refresh();

