js:
var input = root.querySelector('.mdc-group-results-input');
var scroll = root.querySelector('.mdc-group-results-scroll');
var groups = [].slice.call(root.querySelectorAll('.mdc-group-results-group'));
var rows = [].slice.call(root.querySelectorAll('.mdc-group-results-row'));
var empty = root.querySelector('.mdc-group-results-empty');
var crumb = root.querySelector('.mdc-group-results-crumb');
var vis = rows.slice(), i = 0;

function keep(el){
  var t = el.offsetTop - 26, b = el.offsetTop + el.offsetHeight;
  if (t < scroll.scrollTop) scroll.scrollTop = Math.max(0, t);
  else if (b > scroll.scrollTop + scroll.clientHeight) scroll.scrollTop = b - scroll.clientHeight;
}
function paint(){
  rows.forEach(function(r){ r.classList.toggle('is-cursor', r === vis[i]); });
  if (vis[i]) keep(vis[i]);
}
function refresh(){
  var q = input.value.trim().toLowerCase();
  vis = [];
  var live = 0;
  groups.forEach(function(g){
    var kept = 0;
    [].slice.call(g.querySelectorAll('.mdc-group-results-row')).forEach(function(r){
      var hit = r.getAttribute('data-label').toLowerCase().indexOf(q) >= 0;
      r.hidden = !hit;
      if (hit){ kept++; vis.push(r); }
    });
    g.hidden = kept === 0;
    if (kept) live++;
    g.querySelector('.mdc-group-results-n').textContent = String(kept);
  });
  i = 0;
  empty.hidden = vis.length > 0;
  crumb.textContent = vis.length
    ? vis.length + ' result' + (vis.length === 1 ? '' : 's') + ' across ' + live + ' section' + (live === 1 ? '' : 's')
    : 'No match for "' + input.value.trim() + '"';
  paint();
}
function pick(r){
  if (!r) return;
  rows.forEach(function(x){ x.classList.remove('is-picked'); });
  r.classList.add('is-picked');
  crumb.textContent = r.getAttribute('data-group') + ' › ' + r.getAttribute('data-label');
}
function nav(e){
  if (e.key === 'ArrowDown'){ e.preventDefault(); if (vis.length){ i = (i + 1) % vis.length; paint(); } }
  else if (e.key === 'ArrowUp'){ e.preventDefault(); if (vis.length){ i = (i - 1 + vis.length) % vis.length; paint(); } }
  else if (e.key === 'Home'){ e.preventDefault(); i = 0; paint(); }
  else if (e.key === 'End'){ e.preventDefault(); i = Math.max(0, vis.length - 1); paint(); }
  else if (e.key === 'Enter' || e.key === ' '){ e.preventDefault(); pick(vis[i]); }
  else if (e.key === 'Escape' && input.value){ e.preventDefault(); input.value = ''; refresh(); }
}
input.addEventListener('input', refresh);
input.addEventListener('keydown', nav);
rows.forEach(function(r){
  r.addEventListener('keydown', nav);
  r.addEventListener('focus', function(){
    var n = vis.indexOf(r);
    if (n >= 0){ i = n; paint(); }
  });
  r.addEventListener('mousemove', function(){
    var n = vis.indexOf(r);
    if (n >= 0 && n !== i){ i = n; paint(); }
  });
  r.addEventListener('click', function(){
    var n = vis.indexOf(r);
    if (n >= 0){ i = n; paint(); }
    pick(r);
  });
});
refresh();

