js:
var tiles = [].slice.call(root.querySelectorAll('.mdc-action-grid-tile'));
var live = root.querySelector('.mdc-action-grid-live');
var cols = 3, cur = 0, timer = 0;

function ok(n){ return tiles[n] && !tiles[n].disabled; }
function focusAt(n){
  if (!ok(n)) return;
  cur = n;
  tiles.forEach(function(t, k){ t.tabIndex = k === n ? 0 : -1; });
  tiles[n].focus();
}
function move(dr, dc){
  var rowsN = Math.ceil(tiles.length / cols);
  var r = Math.floor(cur / cols), c = cur % cols;
  for (var guard = 0; guard < tiles.length; guard++){
    r = (r + dr + rowsN) % rowsN;
    c = (c + dc + cols) % cols;
    var n = r * cols + c;
    if (ok(n)){ focusAt(n); return; }
  }
}
function fire(t){
  if (!t || t.disabled) return;
  t.classList.add('is-hit');
  live.textContent = t.getAttribute('data-msg');
  clearTimeout(timer);
  timer = setTimeout(function(){
    t.classList.remove('is-hit');
  }, 440);
}
tiles.forEach(function(t, n){
  t.addEventListener('click', function(){ focusAt(n); fire(t); });
  t.addEventListener('focus', function(){ if (!t.disabled) cur = n; });
  t.addEventListener('keydown', function(e){
    if (e.key === 'ArrowRight'){ e.preventDefault(); move(0, 1); }
    else if (e.key === 'ArrowLeft'){ e.preventDefault(); move(0, -1); }
    else if (e.key === 'ArrowDown'){ e.preventDefault(); move(1, 0); }
    else if (e.key === 'ArrowUp'){ e.preventDefault(); move(-1, 0); }
    else if (e.key === 'Home'){ e.preventDefault(); for (var a = 0; a < tiles.length; a++){ if (ok(a)){ focusAt(a); break; } } }
    else if (e.key === 'End'){ e.preventDefault(); for (var b = tiles.length - 1; b >= 0; b--){ if (ok(b)){ focusAt(b); break; } } }
    else if (e.key === 'Enter' || e.key === ' '){ e.preventDefault(); fire(t); }
    else if (e.key >= '1' && e.key <= '6'){
      e.preventDefault();
      var hit = null;
      tiles.forEach(function(x, k){ if (x.getAttribute('data-key') === e.key){ hit = k; } });
      if (hit !== null && ok(hit)){ focusAt(hit); fire(tiles[hit]); }
      else if (hit !== null){ live.textContent = 'Restore is unavailable right now'; }
    }
  });
});

