js:
var list = root.querySelector('.mdc-recent-list-list');
var status = root.querySelector('.mdc-recent-list-status');
var empty = root.querySelector('.mdc-recent-list-empty');
var undo = root.querySelector('.mdc-recent-list-undo');
var clear = root.querySelector('.mdc-recent-list-clear');
var cur = null, bin = [], timer = 0;

function rows(){ return [].slice.call(list.querySelectorAll('.mdc-recent-list-row')); }
function keep(el){
  var t = el.offsetTop, b = t + el.offsetHeight;
  if (t < list.scrollTop) list.scrollTop = t;
  else if (b > list.scrollTop + list.clientHeight) list.scrollTop = b - list.clientHeight;
}
function paint(){
  var all = rows();
  if (all.indexOf(cur) < 0) cur = all[0] || null;
  all.forEach(function(r){
    var on = r === cur;
    r.classList.toggle('is-cursor', on);
    r.setAttribute('aria-selected', on ? 'true' : 'false');
  });
  var pins = all.filter(function(r){ return r.classList.contains('is-pin'); }).length;
  empty.hidden = all.length > 0;
  list.hidden = all.length === 0;
  status.textContent = all.length
    ? all.length + ' item' + (all.length === 1 ? '' : 's') + ' · ' + pins + ' pinned'
    : 'nothing left · P pins, ⌫ removes';
  if (cur) keep(cur);
}
function order(){
  var all = rows();
  all.filter(function(r){ return r.classList.contains('is-pin'); }).forEach(function(r){ list.appendChild(r); });
  all.filter(function(r){ return !r.classList.contains('is-pin'); }).forEach(function(r){ list.appendChild(r); });
}
function pin(r){
  if (!r) return;
  var on = !r.classList.contains('is-pin');
  r.classList.toggle('is-pin', on);
  var btn = r.querySelector('.mdc-recent-list-pin');
  btn.textContent = on ? '◆' : '◇';
  btn.setAttribute('aria-pressed', on ? 'true' : 'false');
  btn.setAttribute('aria-label', (on ? 'Unpin ' : 'Pin ') + r.getAttribute('data-title'));
  order();
  paint();
}
function drop(r){
  if (!r) return;
  var all = rows(), n = all.indexOf(r);
  bin.push({ node: r, at: n });
  undo.hidden = false;
  cur = all[n + 1] || all[n - 1] || null;
  r.classList.add('is-out');
  setTimeout(function(){
    if (r.parentNode) r.parentNode.removeChild(r);
    paint();
  }, 190);
  status.textContent = 'Removed ' + r.getAttribute('data-title');
}
function open(r){
  if (!r) return;
  r.classList.add('is-open');
  status.textContent = 'Opened ' + r.getAttribute('data-title');
  clearTimeout(timer);
  timer = setTimeout(function(){ r.classList.remove('is-open'); }, 520);
}
function step(d){
  var all = rows();
  if (!all.length) return;
  var n = all.indexOf(cur);
  cur = all[(n + d + all.length) % all.length];
  paint();
}
list.addEventListener('keydown', function(e){
  if (e.key === 'ArrowDown'){ e.preventDefault(); step(1); }
  else if (e.key === 'ArrowUp'){ e.preventDefault(); step(-1); }
  else if (e.key === 'Home'){ e.preventDefault(); cur = rows()[0]; paint(); }
  else if (e.key === 'End'){ e.preventDefault(); cur = rows().pop(); paint(); }
  else if (e.key === 'Enter'){ e.preventDefault(); open(cur); }
  else if (e.key === 'p' || e.key === 'P'){ e.preventDefault(); pin(cur); }
  else if (e.key === 'Backspace' || e.key === 'Delete'){ e.preventDefault(); drop(cur); }
});
list.addEventListener('click', function(e){
  var btn = e.target.closest('.mdc-recent-list-pin');
  var row = e.target.closest('.mdc-recent-list-row');
  if (!row) return;
  cur = row;
  if (btn){ pin(row); return; }
  paint();
  open(row);
  list.focus();
});
clear.addEventListener('click', function(){
  rows().forEach(function(r){ if (!r.classList.contains('is-pin')) drop(r); });
});
undo.addEventListener('click', function(){
  var last = bin.pop();
  if (!last) return;
  var all = rows();
  last.node.classList.remove('is-out');
  if (all[last.at]) list.insertBefore(last.node, all[last.at]);
  else list.appendChild(last.node);
  order();
  cur = last.node;
  undo.hidden = bin.length === 0;
  paint();
});
order();
paint();

