js:
var list = root.querySelector('.mdc-key-hints-list');
var rows = [].slice.call(root.querySelectorAll('.mdc-key-hints-row'));
var out = root.querySelector('.mdc-key-hints-chord');
var i = 0, timer = 0;
var MAP = { ArrowUp: '↑', ArrowDown: '↓', ArrowLeft: '←', ArrowRight: '→', Enter: '↵', Escape: 'esc', Backspace: '⌫', Tab: '⇥', ' ': 'space' };
var MODS = { Control: 1, Alt: 1, Shift: 1, Meta: 1 };

function keep(el){
  var t = el.offsetTop, b = t + el.offsetHeight;
  if (t < list.scrollTop) list.scrollTop = t;
  else if (b > list.scrollTop + list.clientHeight) list.scrollTop = b - list.clientHeight;
}
function paint(){
  rows.forEach(function(r, n){
    r.classList.toggle('is-cursor', n === i);
    r.setAttribute('aria-selected', n === i ? 'true' : 'false');
  });
  keep(rows[i]);
}
function chord(e){
  var s = '';
  if (e.metaKey) s += '⌘';
  if (e.ctrlKey) s += '⌃';
  if (e.altKey) s += '⌥';
  if (e.shiftKey) s += '⇧';
  if (MODS[e.key]) return s;
  s += MAP[e.key] || (e.key.length === 1 ? e.key.toUpperCase() : e.key);
  return s;
}
function fire(r){
  if (!r) return;
  i = rows.indexOf(r);
  paint();
  r.classList.add('is-fire');
  out.textContent = r.getAttribute('data-chord') + ' · ' + r.getAttribute('data-act');
  clearTimeout(timer);
  timer = setTimeout(function(){ r.classList.remove('is-fire'); }, 480);
}
list.addEventListener('keydown', function(e){
  if (e.key === 'ArrowDown' && !e.metaKey && !e.ctrlKey && !e.altKey){ e.preventDefault(); i = (i + 1) % rows.length; paint(); return; }
  if (e.key === 'ArrowUp' && !e.metaKey && !e.ctrlKey && !e.altKey){ e.preventDefault(); i = (i - 1 + rows.length) % rows.length; paint(); return; }
  if (e.key === 'Enter'){ e.preventDefault(); fire(rows[i]); return; }
  var c = chord(e);
  if (!c || MODS[e.key]){ out.textContent = c ? c + '…' : 'waiting'; return; }
  var hit = null;
  rows.forEach(function(r){ if (r.getAttribute('data-chord') === c) hit = r; });
  if (hit){ e.preventDefault(); fire(hit); }
  else out.textContent = c + ' · unassigned';
});
list.addEventListener('keyup', function(e){
  if (MODS[e.key]) out.textContent = 'press a shortcut';
});
list.addEventListener('focus', function(){ out.textContent = 'press a shortcut'; });
list.addEventListener('blur', function(){ out.textContent = 'focus me, then press keys'; });
rows.forEach(function(r, n){
  r.addEventListener('click', function(){ fire(r); list.focus(); });
  r.addEventListener('mousemove', function(){ if (i !== n){ i = n; paint(); } });
});
paint();

css:
.mdc-context-menu{
  --mdc-cm-line:rgba(255,255,255,.09);
  --mdc-cm-txt:#E7EBF4;
  --mdc-cm-dim:#7B8399;
  --mdc-cm-accent:#7DD3FC;
  --mdc-cm-danger:#FF7A85;
  position:relative;box-sizing:border-box;width:100%;max-width:320px;min-height:202px;margin:0 auto;padding:10px;
  border:1px solid var(--mdc-cm-line);border-radius:13px;overflow:hidden;
  background:radial-gradient(130% 110% at 100% 0,#171B25,#0B0D13 65%);
  color:var(--mdc-cm-txt);font:500 12px/1.3 system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
.mdc-context-menu *{box-sizing:border-box}
