.mdc-context-menu-title{font:700 9px/1 system-ui,sans-serif;letter-spacing:.16em;text-transform:uppercase;color:var(--mdc-cm-dim)}
.mdc-context-menu-cue{font:600 8.5px/1 ui-monospace,Menlo,monospace;color:var(--mdc-cm-dim);border:1px solid var(--mdc-cm-line);border-radius:5px;padding:4px 5px}
.mdc-context-menu-rows{display:flex;flex-direction:column;gap:4px}
.mdc-context-menu-row{
  display:flex;align-items:center;gap:9px;padding:7px 8px;border-radius:9px;cursor:context-menu;
  border:1px solid transparent;background:rgba(255,255,255,.03);transition:background .15s ease,border-color .15s ease;
}
.mdc-context-menu-row:hover{background:rgba(125,211,252,.06);border-color:rgba(125,211,252,.22)}
.mdc-context-menu-row.is-on{border-color:rgba(125,211,252,.35);background:rgba(125,211,252,.08)}
.mdc-context-menu-row:focus{outline:none}
.mdc-context-menu-row:focus-visible{outline:2px solid var(--mdc-cm-accent);outline-offset:1px}
.mdc-context-menu-doc{flex:none;display:grid;place-items:center;width:26px;height:26px;border-radius:7px;background:rgba(125,211,252,.12)}
.mdc-context-menu-doc svg{width:14px;height:14px;fill:none;stroke:var(--mdc-cm-accent);stroke-width:1.6;stroke-linejoin:round;stroke-linecap:round}
.mdc-context-menu-info{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}
.mdc-context-menu-name{font-size:11.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mdc-context-menu-meta{font-size:9px;color:var(--mdc-cm-dim);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mdc-context-menu-dots{flex:none;width:20px;height:20px;border:0;border-radius:6px;background:none;color:var(--mdc-cm-dim);font:600 13px/1 system-ui,sans-serif;cursor:pointer;transition:background .14s ease,color .14s ease}
.mdc-context-menu-dots:hover{background:rgba(255,255,255,.09);color:var(--mdc-cm-txt)}
.mdc-context-menu-pop{
  position:absolute;z-index:5;min-width:158px;padding:5px;border-radius:11px;
  border:1px solid rgba(255,255,255,.12);background:rgba(19,22,31,.97);
  box-shadow:0 20px 40px -18px #000,0 0 0 1px rgba(0,0,0,.5);
  transform-origin:top left;animation:mdc-context-menu-open .16s cubic-bezier(.2,.9,.3,1) both;
}
.mdc-context-menu-item{
  position:relative;display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;
  height:26px;padding:0 8px;border:0;border-radius:7px;background:none;cursor:pointer;
  color:var(--mdc-cm-txt);font:500 11.5px/1 inherit;text-align:left;transition:background .12s ease,color .12s ease;
}
.mdc-context-menu-item:hover{background:rgba(255,255,255,.07)}
.mdc-context-menu-item.is-on{background:rgba(125,211,252,.16)}
.mdc-context-menu-item:focus{outline:none}
.mdc-context-menu-item:focus-visible{outline:2px solid var(--mdc-cm-accent);outline-offset:-2px}
.mdc-context-menu-danger{color:var(--mdc-cm-danger)}
.mdc-context-menu-danger:hover,.mdc-context-menu-danger.is-on{background:rgba(255,122,133,.14)}
