  position:absolute;left:calc(100% - 2px);top:-6px;min-width:118px;padding:5px;border-radius:10px;
  border:1px solid rgba(255,255,255,.12);background:rgba(19,22,31,.98);
  box-shadow:0 16px 32px -16px #000;animation:mdc-context-menu-slide .15s ease both;
