.mdc-context-menu-log.is-hot{color:var(--mdc-cm-accent);border-color:rgba(125,211,252,.35)}
@keyframes mdc-context-menu-open{from{opacity:0;transform:scale(.92)}to{opacity:1;transform:scale(1)}}
@keyframes mdc-context-menu-slide{from{opacity:0;transform:translateX(-5px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion: reduce){
.mdc-context-menu-pop{animation:none}
.mdc-context-menu-sub{animation:none}
.mdc-context-menu-item{transition:none}
.mdc-context-menu-row{transition:none}
}

js:
var rows = [].slice.call(root.querySelectorAll('.mdc-context-menu-row'));
var pop = root.querySelector('.mdc-context-menu-pop');
var more = root.querySelector('.mdc-context-menu-more');
var sub = root.querySelector('.mdc-context-menu-sub');
var log = root.querySelector('.mdc-context-menu-log');
var l1 = [].slice.call(root.querySelectorAll('.mdc-context-menu-l1'));
var l2 = [].slice.call(root.querySelectorAll('.mdc-context-menu-l2'));
var items = l1, i = 0, row = 0, timer = 0;

function selectRow(n){
  row = (n + rows.length) % rows.length;
  rows.forEach(function(r, k){
    r.classList.toggle('is-on', k === row);
    r.setAttribute('aria-selected', k === row ? 'true' : 'false');
    r.tabIndex = k === row ? 0 : -1;
  });
}
function mark(){
  l1.concat(l2).forEach(function(b){ b.classList.remove('is-on'); });
  if (items[i]){ items[i].classList.add('is-on'); items[i].focus(); }
}
function openSub(on){
  sub.hidden = !on;
  more.setAttribute('aria-expanded', on ? 'true' : 'false');
  if (on){
    sub.classList.remove('is-left');
    var r = sub.getBoundingClientRect(), rr = root.getBoundingClientRect();
    if (r.right > rr.right - 4) sub.classList.add('is-left');
    items = l2;
    i = 0;
  } else {
    items = l1;
    i = l1.indexOf(more);
  }
  mark();
}
function open(x, y){
  pop.hidden = false;
  openSub(false);
  var w = pop.offsetWidth, h = pop.offsetHeight;
  pop.style.left = Math.max(6, Math.min(x, root.clientWidth - w - 6)) + 'px';
  pop.style.top = Math.max(6, Math.min(y, root.clientHeight - h - 6)) + 'px';
  items = l1;
  i = 0;
  mark();
}
function close(back){
  if (pop.hidden) return;
  sub.hidden = true;
  pop.hidden = true;
  if (back) rows[row].focus();
}
function run(btn){
  log.textContent = btn.getAttribute('data-act') + ' ' + rows[row].getAttribute('data-file');
  log.classList.add('is-hot');
  clearTimeout(timer);
  timer = setTimeout(function(){ log.classList.remove('is-hot'); }, 1600);
  close(true);
}
rows.forEach(function(r, n){
  r.addEventListener('contextmenu', function(e){
    e.preventDefault();
    selectRow(n);
    var b = root.getBoundingClientRect();
    open(e.clientX - b.left, e.clientY - b.top);
  });
  r.addEventListener('focus', function(){ selectRow(n); });
  r.addEventListener('keydown', function(e){
    if (e.key === 'ArrowDown'){ e.preventDefault(); selectRow(row + 1); rows[row].focus(); }
    else if (e.key === 'ArrowUp'){ e.preventDefault(); selectRow(row - 1); rows[row].focus(); }
    else if (e.key === 'Enter' || e.key === ' ' || e.key === 'ContextMenu'){
      e.preventDefault();
      selectRow(n);
      var b = root.getBoundingClientRect(), rb = r.getBoundingClientRect();
      open(30, rb.bottom - b.top + 2);
    }
  });
  r.querySelector('.mdc-context-menu-dots').addEventListener('click', function(e){
    e.stopPropagation();
    selectRow(n);
    var b = root.getBoundingClientRect(), db = e.currentTarget.getBoundingClientRect();
    open(db.left - b.left - 140, db.bottom - b.top + 2);
  });
});
l1.concat(l2).forEach(function(btn){
  btn.addEventListener('mousemove', function(){
    var n = items.indexOf(btn);
    if (n >= 0 && n !== i){ i = n; mark(); }
  });
  btn.addEventListener('click', function(e){
    e.stopPropagation();
    if (btn === more){ openSub(sub.hidden); return; }
    run(btn);
  });
  btn.addEventListener('keydown', function(e){
    if (e.key === 'ArrowDown'){ e.preventDefault(); i = (i + 1) % items.length; mark(); }
    else if (e.key === 'ArrowUp'){ e.preventDefault(); i = (i - 1 + items.length) % items.length; mark(); }
    else if (e.key === 'ArrowRight' && btn === more){ e.preventDefault(); openSub(true); }
    else if (e.key === 'ArrowLeft' && items === l2){ e.preventDefault(); openSub(false); }
    else if (e.key === 'Escape'){ e.preventDefault(); if (items === l2) openSub(false); else close(true); }
    else if ((e.key === 'Enter' || e.key === ' ') && btn === more){ e.preventDefault(); openSub(sub.hidden); }
  });
});
root.addEventListener('pointerdown', function(e){
  if (!pop.hidden && !pop.contains(e.target)) close(false);
});
selectRow(0);

css:
.mdc-omni-inline{
  --mdc-om-line:rgba(255,255,255,.09);
  --mdc-om-txt:#E8EDF7;
  --mdc-om-dim:#727C93;
  --mdc-om-accent:#5EE7D8;
  box-sizing:border-box;width:100%;max-width:320px;margin:0 auto;
  font:500 12px/1.3 system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;color:var(--mdc-om-txt);
}
.mdc-omni-inline *{box-sizing:border-box}
.mdc-omni-inline-field{
  display:flex;align-items:center;gap:8px;padding:5px 6px 5px 6px;border-radius:999px;
  border:1px solid var(--mdc-om-line);background:linear-gradient(180deg,#151A24,#0C0F16);
  transition:border-color .16s ease,box-shadow .16s ease;
