.mdc-omni-inline-wrap{position:relative;flex:1;min-width:0;height:22px}
.mdc-omni-inline-ghost{position:absolute;left:0;top:0;right:0;height:22px;line-height:22px;font:500 12px/22px system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;white-space:pre;overflow:hidden;pointer-events:none}
