js:
var field = root.querySelector('.mdc-omni-inline-field');
var input = root.querySelector('.mdc-omni-inline-input');
var mode = root.querySelector('.mdc-omni-inline-mode');
var typed = root.querySelector('.mdc-omni-inline-typed');
var rest = root.querySelector('.mdc-omni-inline-rest');
var menu = root.querySelector('.mdc-omni-inline-menu');
var opts = [].slice.call(root.querySelectorAll('.mdc-omni-inline-opt'));
var out = root.querySelector('.mdc-omni-inline-out');
var none = document.createElement('li');
none.className = 'mdc-omni-inline-none';
none.textContent = 'No match';
none.hidden = true;
menu.appendChild(none);
var vis = opts.slice(), i = 0;
var MODES = { '>': ['cmd', 'Run'], '@': ['person', 'Who'], '#': ['issue', 'Issue'] };
var VERB = { cmd: 'Ran', person: 'Opened profile', issue: 'Opened issue' };

function parse(){
  var v = input.value;
  var p = v.charAt(0);
  if (MODES[p]) return { type: MODES[p][0], label: MODES[p][1], prefix: p, q: v.slice(1).replace(/^\s+/, '') };
  return { type: 'all', label: 'All', prefix: '', q: v };
}
function keep(el){
  var t = el.offsetTop, b = t + el.offsetHeight;
  if (t < menu.scrollTop) menu.scrollTop = t;
  else if (b > menu.scrollTop + menu.clientHeight) menu.scrollTop = b - menu.clientHeight;
}
function paint(){
  opts.forEach(function(o){
    var on = o === vis[i];
    o.classList.toggle('is-on', on);
    o.setAttribute('aria-selected', on ? 'true' : 'false');
  });
  if (vis[i]) keep(vis[i]);
}
function ghost(state){
  var top = vis[0];
  typed.textContent = '';
  rest.textContent = '';
  if (!state.q || !top) return;
  var label = top.getAttribute('data-label');
  if (label.toLowerCase().indexOf(state.q.toLowerCase()) === 0){
    typed.textContent = input.value;
    rest.textContent = label.slice(state.q.length);
  }
}
function refresh(){
  var s = parse();
  field.setAttribute('data-mode', s.type);
  mode.textContent = s.label;
  var q = s.q.toLowerCase();
  vis = [];
  opts.forEach(function(o){
    var hit = (s.type === 'all' || o.getAttribute('data-type') === s.type)
      && o.getAttribute('data-label').toLowerCase().indexOf(q) >= 0;
    o.hidden = !hit;
    if (hit) vis.push(o);
  });
  none.hidden = vis.length > 0;
  i = 0;
  ghost(s);
  paint();
}
function commit(o){
  if (!o) return;
  var t = o.getAttribute('data-type');
  out.textContent = VERB[t] + ' · ' + o.getAttribute('data-label');
  out.classList.remove('is-flash');
  void out.offsetWidth;
  out.classList.add('is-flash');
}
input.addEventListener('input', refresh);
input.addEventListener('keydown', function(e){
  if (e.key === 'ArrowDown'){ e.preventDefault(); if (vis.length){ i = (i + 1) % vis.length; paint(); } }
  else if (e.key === 'ArrowUp'){ e.preventDefault(); if (vis.length){ i = (i - 1 + vis.length) % vis.length; paint(); } }
  else if (e.key === 'Tab' && rest.textContent){
    e.preventDefault();
    var s = parse();
    input.value = s.prefix + vis[0].getAttribute('data-label');
    refresh();
  }
  else if (e.key === 'Enter'){ e.preventDefault(); commit(vis[i]); }
  else if (e.key === 'Escape' && input.value){ e.preventDefault(); input.value = ''; refresh(); }
});
opts.forEach(function(o){
  o.addEventListener('mousemove', function(){
    var n = vis.indexOf(o);
    if (n >= 0 && n !== i){ i = n; paint(); }
  });
  o.addEventListener('click', function(){
    var n = vis.indexOf(o);
    if (n >= 0){ i = n; paint(); }
    commit(o);
    input.focus();
  });
});
refresh();
